// starts the localStorage of a storage directory that has none yet with what another browser
// kept, so the entries are read only once; entries past the limits setItem holds pages to are
// left behind, and it says whether it seeded
pub fn seed_local_storage(
    directory: impl AsRef<Path>,
    entries: impl FnOnce() -> io::Result<Vec<(String, String)>>,
) -> io::Result<bool> {
    if directory.as_ref().join(STORAGE_FILE_NAME).exists() {
        return Ok(false);
    }
    let mut storage = StorageData::load_from_directory(directory)?;
    storage.values.extend(
        entries()?
            .into_iter()
            .filter(|(key, value)| {
                key.len() <= MAX_STORAGE_TEXT_BYTES && value.len() <= MAX_STORAGE_VALUE_BYTES
            })
            .take(MAX_STORAGE_VALUES),
    );
    storage.persist()?;
    Ok(true)
}

pub(crate) struct StorageData {
    values: BTreeMap<String, String>,
    caches: BTreeMap<String, CacheHandle>,
    cache_order: Vec<String>,
    databases: BTreeMap<String, IndexedDbDatabaseHandle>,
    database_order: Vec<String>,
    persistence_path: Option<PathBuf>,
    // the bytes last read from or written to the file, so an unchanged store is not rewritten
    persisted: RefCell<Vec<u8>>,
}

impl StorageData {
    // what the store holds on disk, or its keys and values while it has not been written
    pub(crate) fn byte_size(&self) -> usize {
        match self.persisted.borrow().len() {
            0 => self
                .values
                .iter()
                .map(|(key, value)| key.len() + value.len())
                .sum(),
            written => written,
        }
    }

    pub(crate) fn new() -> Self {
        Self {
            values: BTreeMap::new(),
            caches: BTreeMap::new(),
            cache_order: Vec::new(),
            databases: BTreeMap::new(),
            database_order: Vec::new(),
            persistence_path: None,
            persisted: RefCell::new(Vec::new()),
        }
    }

    pub(crate) fn load_from_directory(directory: impl AsRef<Path>) -> io::Result<Self> {
        let directory = directory.as_ref();
        fs::create_dir_all(directory)?;
        let directory = fs::canonicalize(directory)?;
        if !fs::metadata(&directory)?.is_dir() {
            return Err(io::Error::new(
                io::ErrorKind::InvalidInput,
                "storage root is not a directory",
            ));
        }
        let path = directory.join(STORAGE_FILE_NAME);
        let mut storage = if path.exists() {
            if !fs::metadata(&path)?.is_file() {
                return Err(io::Error::new(
                    io::ErrorKind::InvalidInput,
                    "storage file path is not a regular file",
                ));
            }
            let bytes = fs::read(&path)?;
            let storage = decode_storage(&bytes)?;
            *storage.persisted.borrow_mut() = bytes;
            storage
        } else {
            Self::new()
        };
        storage.persistence_path = Some(path);
        Ok(storage)
    }

    pub(crate) fn persist(&self) -> io::Result<()> {
        let Some(path) = self.persistence_path.as_deref() else {
            return Ok(());
        };
        let bytes = encode_storage(self)?;
        if *self.persisted.borrow() == bytes {
            return Ok(());
        }
        atomic_write(path, &bytes)?;
        *self.persisted.borrow_mut() = bytes;
        Ok(())
    }
}

