fn typed_object(array: &TypedArrayHandle) -> object::ObjectHandle {
    let mut array = array.borrow_mut();
    let kind = array.kind;
    array
        .object
        .get_or_insert_with(|| {
            object::new_object(object::JsObject::with_class(
                object::ObjectClass::TypedArray(kind),
            ))
        })
        .clone()
}

