    #[test]
    fn a_rejection_nothing_handles_reaches_the_window_and_the_console() {
        let document = document("<p id='status'>idle</p>");
        let mut runtime = ScriptRuntime::new(document.clone());
        runtime
            .execute(
                r#"
                const seen = [];
                addEventListener("unhandledrejection", (event) => {
                    seen.push(event.type + ":" + (event.reason?.message ?? event.reason) + ":" + (event.promise instanceof Promise));
                    if (event.reason === "quiet") event.preventDefault();
                    document.getElementById("status").textContent = seen.join(" ");
                });
                Promise.reject(new Error("lost"));
                Promise.reject("quiet");
                Promise.reject(new Error("caught")).catch(() => {});
                (async () => { throw new Error("thrown"); })();
                const later = Promise.reject(new Error("awaited"));
                (async () => { try { await later; } catch {} })();
                Promise.reject(new Error("chained")).then(() => {});
                "#,
            )
            .expect("rejections should be reported, not thrown");
        let status = document
            .borrow()
            .find_element_by_id("status")
            .expect("status should exist");
        assert_eq!(
            document.borrow().element_text_content(status).as_deref(),
            Some(
                "unhandledrejection:lost:true unhandledrejection:quiet:true unhandledrejection:thrown:true unhandledrejection:chained:true"
            )
        );
        let logs = runtime.logs().join("|");
        assert!(logs.contains("Uncaught (in promise) Error: lost"), "{logs}");
        assert!(
            logs.contains("Uncaught (in promise) Error: chained"),
            "{logs}"
        );
        assert!(
            !logs.contains("quiet") && !logs.contains("Error: caught") && !logs.contains("awaited"),
            "{logs}"
        );
    }

    #[test]
    fn promise_all_over_async_callbacks_that_catch_settles_with_their_values() {
        let document = document("<p id='status'>idle</p>");
        let mut runtime = ScriptRuntime::new(document.clone());
        runtime
            .execute(
                r#"
                const ask = (id) => (id === "bad" ? Promise.reject(new Error("no")) : Promise.resolve({ id }));
                let turn = 0;
                async function refresh() {
                    const current = ++turn;
                    try {
                        const catalog = await Promise.resolve([{ id: "a", on: true }, { id: "bad", on: true }, { id: "c", on: false }, { id: "d", on: true }]);
                        if (current !== turn) return;
                        const ids = await Promise.all(
                            catalog
                                .filter((entry) => entry.on)
                                .map(async (entry) => {
                                    try {
                                        await ask(entry.id);
                                        return entry.id;
                                    } catch {
                                        return null;
                                    }
                                }),
                        );
                        if (current !== turn) return;
                        const kept = new Set(ids.filter((id) => id !== null));
                        document.getElementById("status").textContent = [...kept].join(",") + " " + kept.has("d");
                    } catch {
                        document.getElementById("status").textContent = "failed";
                    }
                }
                refresh();
                "#,
            )
            .expect("the refresh should run");
        let status = document
            .borrow()
            .find_element_by_id("status")
            .expect("status should exist");
        assert_eq!(
            document.borrow().element_text_content(status).as_deref(),
            Some("a,d true")
        );
    }

    #[test]
    fn an_array_made_with_a_length_has_holes_until_they_are_filled() {
        let document = document("<p id='status'>idle</p>");
        let mut runtime = ScriptRuntime::new(document.clone());
        runtime
            .execute(
                r#"
                const temp = new Array(4);
                temp[2] = "kept";
                const seen = [0 in temp, 2 in temp, 3 in temp, temp.length, temp.hasOwnProperty(1)];
                const visited = [];
                temp.forEach((value, index) => visited.push(index));
                seen.push(visited.join("/"), Object.keys(temp).join("/"), temp[0] === undefined);
                const literal = [1, , 3];
                seen.push(1 in literal, literal.length);
                delete literal[0];
                seen.push(0 in literal);
                const gap = [1, , 3];
                seen.push(gap.join("-"), String(gap), JSON.stringify(gap), [...gap].length, 1 in [...gap]);
                seen.push(1 in gap.map((value) => value * 2), gap.filter(() => true).length);
                seen.push(gap.reduce((sum, value) => sum + value, 0), gap.indexOf(undefined), gap.includes(undefined));
                seen.push(new Array(3).fill(0).join(), Array.from(new Array(2)).length, 0 in Array.from(new Array(2)));
                seen.push(gap.slice(0, 2).length, 1 in gap.slice(0, 2), 1 in gap.concat([4]), gap.some((value) => value === undefined));
                const [first, second = "default"] = gap;
                let counted = 0;
                for (const key in gap) counted += 1;
                seen.push(second, counted, gap.findIndex((value) => value === undefined), Object.entries(gap).length);
                document.getElementById("status").textContent = seen.join(" ");
                "#,
            )
            .expect("sparse arrays should run");
        let status = document
            .borrow()
            .find_element_by_id("status")
            .expect("status should exist");
        assert_eq!(
            document.borrow().element_text_content(status).as_deref(),
            Some(
                "false true false 4 false 2 2 true false 3 false 1--3 1,,3 [1,null,3] 3 true false 2 4 -1 true 0,0,0 2 true 2 false false false default 2 1 2"
            )
        );
    }

