    #[test]
    fn writes_through_the_property_cache_keep_every_rule_of_assignment() {
        let document = document(r#"<main><p id="status">idle</p></main>"#);
        let mut runtime = ScriptRuntime::new(document.clone());
        runtime
            .execute(
                r#"
                "use strict";
                const out = [];
                const write = (target, value) => { try { target.v = value; return target.v; } catch (error) { return error.name; } };
                const plain = { v: 0 };
                for (let i = 1; i < 4; i++) write(plain, i);
                out.push(write(plain, 5));
                Object.defineProperty(plain, "v", { writable: false }); out.push(write(plain, 6));
                const proto = { set v(x) { out.push("setter " + x); } };
                const child = Object.create(proto); out.push(write(child, 1));
                const owned = Object.create(proto); Object.defineProperty(owned, "v", { value: 1, writable: true, enumerable: true, configurable: true }); out.push(write(owned, 2)); out.push(write(owned, 3));
                const frozen = { v: 1 }; write(frozen, 2); Object.freeze(frozen); out.push(write(frozen, 3));
                const deleted = { v: 1 }; write(deleted, 2); delete deleted.v; out.push(write(deleted, 4));
                const seen = []; const proxy = new Proxy({ v: 1 }, { set(target, key, value) { seen.push(value); target[key] = value; return true; } }); write(proxy, 7); write(proxy, 8); out.push(seen.join("+"));
                const getter = { get v() { return "g"; } }; out.push(write(getter, 1));
                document.getElementById("status").textContent = out.join(",");
                "#,
            )
            .expect("script should run");
        assert_eq!(
            status_text(&document).as_deref(),
            Some("5,TypeError,setter 1,,2,3,TypeError,4,7+8,TypeError")
        );
    }
    #[test]
    fn reads_through_a_prototype_follow_every_change_to_it() {
        let document = document(r#"<main><p id="status">idle</p></main>"#);
        let mut runtime = ScriptRuntime::new(document.clone());
        runtime
            .execute(
                r#"
                const out = [];
                const proto = { greet() { return "a"; }, n: 1 };
                const read = (object) => object.greet() + object.n;
                const one = Object.create(proto);
                for (let i = 0; i < 3; i++) read(one);
                out.push(read(one));
                proto.greet = () => "b"; out.push(read(one));
                one.greet = () => "own"; out.push(read(one)); delete one.greet; out.push(read(one));
                delete proto.n; out.push(read(one)); proto.n = 2; out.push(read(one));
                Object.setPrototypeOf(one, { greet: () => "c", n: 3 }); out.push(read(one));
                Object.defineProperty(proto, "n", { get: () => 4 }); out.push(read(Object.create(proto)));
                const big = {}; for (let k = 0; k < 80; k++) big["k" + k] = k; big.greet = () => "d"; big.n = 5;
                const two = Object.create(big); out.push(read(two)); delete big.k3; big.n = 6; out.push(read(two));
                delete big.n; out.push(read(two)); big.n = 7; out.push(read(two));
                const list = [1, 2];
                const push = (array, value) => array.push(value);
                push(list, 3); push(list, 4); out.push(list.length);
                const saved = Array.prototype.push;
                Array.prototype.push = function () { return "patched"; }; out.push(push(list, 5));
                Array.prototype.push = saved; out.push(push(list, 5));
                list.push = () => "own push"; out.push(push(list, 6)); delete list.push;
                Object.setPrototypeOf(list, { push: () => "other" }); out.push(push(list, 7));
                document.getElementById("status").textContent = out.join(",");
                "#,
            )
            .expect("script should run");
        assert_eq!(
            status_text(&document).as_deref(),
            Some("a1,b1,own1,b1,bundefined,b2,c3,b4,d5,d6,dundefined,d7,4,5,own push,other")
        );
    }
    #[test]
    fn blocks_nothing_captures_keep_their_scoping_rules() {
        let document = document(r#"<main><p id="status">idle</p></main>"#);
        let mut runtime = ScriptRuntime::new(document.clone());
        runtime
            .execute(
                r#"
                const out = [];
                function run() {
                    let x = "outer";
                    for (let i = 0; i < 3; i++) {
                        try { out.push(late); } catch (error) { out.push(error.name); }
                        let late = i;
                        { let x = "inner" + i; out.push(x); }
                        if (i === 1) continue;
                        try { if (i === 2) break; } finally { out.push("finally" + i); }
                    }
                    out.push(x);
                    try { throw "thrown"; } catch (caught) { let x = caught; out.push(x); }
                    const kept = [];
                    for (let j = 0; j < 2; j++) { const v = j * 10; kept.push(() => v); }
                    out.push(kept.map((read) => read()).join("+"));
                    label: for (const a of [1, 2]) { for (const b of [1, 2]) { if (b === 2) continue label; out.push(a + "" + b); } }
                    return out.join(",");
                }
                function* numbers(tag) { try { yield 1; yield 2; } finally { out.push("closed" + tag); } }
                function exits() {
                    l1: for (const a of numbers("a")) { for (const b of numbers("b" + a)) { try { if (b === 2) continue l1; } finally { out.push("finally" + a + b); } out.push(a + "" + b); } }
                    l2: for (const a in { x: 1, y: 2 }) { for (const b of [1, 2]) { if (b === 2) break l2; out.push(a + b); } }
                }
                const first = run();
                out.length = 0;
                exits();
                document.getElementById("status").textContent = first + "|" + out.join(",");
                "#,
            )
            .expect("script should run");
        assert_eq!(
            status_text(&document).as_deref(),
            Some(
                "ReferenceError,inner0,finally0,ReferenceError,inner1,ReferenceError,inner2,finally2,outer,thrown,0+10,11,21|finally11,11,finally12,closedb1,finally21,21,finally22,closedb2,closeda,x1"
            )
        );
    }
