    #[test]
    fn a_class_list_reads_as_the_ordered_set_of_its_tokens() {
        let document = document("<p id='status' class='a b  c b'>idle</p>");
        let mut runtime = ScriptRuntime::new(document.clone());
        runtime
            .execute(
                r##"
                const status = document.getElementById("status");
                const list = status.classList;
                const seen = [list.length, list.value, list.item(1), list.item(9), list[0], list[9]];
                seen.push([...list].join());
                const walked = [];
                list.forEach((name, index) => walked.push(index + name));
                for (const name of list) walked.push(name);
                seen.push(walked.join(""), [...list.entries()].join("|"));
                seen.push(list.replace("b", "z"), list.replace("missing", "y"), status.className);
                seen.push(list.replace("a", "c"), String(list), `${list}`, list.toString());
                list.value = "one two";
                seen.push(list.length, list.contains("two"), list.missing);
                try {
                    list.supports("x");
                } catch (error) {
                    seen.push(error.name);
                }
                status.textContent = seen.join(" ");
                "##,
            )
            .expect("classList reads should execute");
        let status = document
            .borrow()
            .find_element_by_id("status")
            .expect("status should exist");
        assert_eq!(
            document.borrow().element_text_content(status).as_deref(),
            Some(
                "3 a b  c b b  a  a,b,c 0a1b2cabc 0,a|1,b|2,c true false a z c true c z c z c z 2 true  TypeError"
            )
        );
    }

    #[test]
    fn mutates_attached_and_detached_classes_through_class_list() {
        let document = document("<main id='mount'><p id='status' class='ready'>idle</p></main>");
        let mut runtime = ScriptRuntime::new(document.clone());
        runtime
            .execute(
                r##"
                const mount = document.getElementById("mount");
                const status = document.getElementById("status");
                status.classList.add("active", "open");
                status.classList.remove("ready");
                status.classList.toggle("open");
                status.classList.toggle("selected", true);
                if (!status.classList.contains("open") && status.classList.contains("selected")) {
                    status.textContent = status.className;
                }
                const card = document.createElement("section");
                card.classList.add("created");
                mount.appendChild(card);
                card.classList.toggle("created", false);
                "##,
            )
            .expect("classList mutations should execute");
        let status = document
            .borrow()
            .find_element_by_id("status")
            .expect("status should exist");
        assert_eq!(
            document
                .borrow()
                .attribute(status, "class")
                .map(str::to_string)
                .as_deref(),
            Some("active selected")
        );
        assert_eq!(
            document.borrow().element_text_content(status).as_deref(),
            Some("active selected")
        );
        let created = document
            .borrow()
            .find_element_by_selector("section")
            .expect("created element should exist");
        assert_eq!(
            document
                .borrow()
                .attribute(created, "class")
                .map(str::to_string)
                .as_deref(),
            Some("")
        );
    }

